from __future__ import annotations

import re
import shutil
from pathlib import Path

MOVIE_EXTS = {'.mkv', '.mp4', '.m4v', '.avi', '.mov', '.webm', '.ts', '.m2ts', '.wmv'}
SUB_EXTS = {'.srt', '.ass', '.ssa', '.sub', '.vtt', '.sup'}
VIDEO_EXTS = MOVIE_EXTS
LOG = Path('/tmp/jellyfin-organize.log')

log_lines: list[str] = []
def log(action: str, src: Path, dst: Path | None = None) -> None:
    line = action if dst is None else f'{action}: {src} -> {dst}'
    print(line)
    log_lines.append(line)

def ensure_empty_or_absent(path: Path) -> None:
    if path.exists() and any(path.iterdir()):
        raise RuntimeError(f'target is not empty: {path}')

def move_entry(src: Path, dst: Path) -> None:
    if not src.exists():
        return
    if dst.exists():
        raise RuntimeError(f'collision: {src} -> {dst}')
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dst))
    log('MOVE', src, dst)

def merge_dir_contents(src: Path, dst: Path) -> None:
    dst.mkdir(parents=True, exist_ok=True)
    for child in sorted(src.iterdir(), key=lambda p: p.name.casefold()):
        target = dst / child.name
        if target.exists():
            raise RuntimeError(f'collision while merging: {child} -> {target}')
        shutil.move(str(child), str(target))
        log('MOVE', child, target)
    if src.exists() and not any(src.iterdir()):
        src.rmdir()
        log('RMDIR', src)

def normalize_sidecars(folder: Path, old_stem: str, new_stem: str) -> None:
    for item in list(folder.iterdir()):
        if not item.is_file() or item.suffix.lower() not in SUB_EXTS:
            continue
        if item.stem == old_stem or item.name.startswith(old_stem + '.'):
            suffix = item.name[len(old_stem):]
            target = folder / (new_stem + suffix)
            if target != item:
                move_entry(item, target)

def normalize_movie_folder(folder: Path) -> None:
    videos = sorted([p for p in folder.iterdir() if p.is_file() and p.suffix.lower() in VIDEO_EXTS])
    if len(videos) == 1:
        video = videos[0]
        new_video = folder / (folder.name + video.suffix.lower())
        old_stem = video.stem
        if video != new_video:
            move_entry(video, new_video)
        normalize_sidecars(folder, old_stem, folder.name)
    elif len(videos) > 1:
        # Keep multiple versions, but make each filename use the folder prefix.
        for video in videos:
            if video.stem.startswith(folder.name):
                continue
            new_video = folder / (folder.name + ' - ' + video.stem + video.suffix.lower())
            move_entry(video, new_video)
            normalize_sidecars(folder, video.stem, new_video.stem)

def prepare_movie_folder(source: Path | None, target: Path, loose_files: list[Path] = []) -> None:
    if source is not None and source != target:
        if target.exists():
            raise RuntimeError(f'movie target collision: {source} -> {target}')
        source.rename(target)
        log('RENAME_DIR', source, target)
    else:
        target.mkdir(parents=True, exist_ok=True)
    for item in loose_files:
        move_entry(item, target / item.name)
    normalize_movie_folder(target)

